  function setPbkyes (amount: any) {

    pbkSet= new Array(grateNumber + 2);

    pbkSet [0] = pubKeyGen[0];
    numbeKeys = 0;
    numbeKeys ++;

    //console.log("Return: ", await setAlertWait(0));
   
    //Soma o ponto Delta ao ponto de partida para chegar ao proximo ponto
    for(let i = 0; i < grateNumber; i++){
  
      pubKeyGen = keyGen.keys.addp(pubKeyGen[0], pubKeyGen[1], pubKeyGenDelta[0], pubKeyGenDelta[1]);
      pbkSet [i + 1] = pubKeyGen[0];
  
      if(i % 10000 === 1){
        console.log("Point Creating: ", i)
        //console.log("Nkeys: ", numbeKeys)
        //setnKeys(numbeKeys);
        //sharedState.value = numbeKeys;
      }

      numbeKeys ++;

      //if(i === 0)
      //  console.log("Point range 1: ", pubKeyGen[0].toString(16))
    }
  
    //Utimo ponto da serie
    pbkSet [grateNumber + 1] = keyGen.keys.eccnP(pvtKeyF, keyGen.keys.Gx, keyGen.keys.Gy)[0];

    numbeKeys ++;
  
    console.log("pbkset: ", pbkSet)
  
    //setwaitAlert("Inform range and hit start to begin search");
  };
