  /////////////////////////////////////////////////
  //Jesus is the Lord
  //  Collision search
  /////////////////////////////////////////////////
  function searchPbkey (rangeAmount: number, rangeCycles: number): string {

    let pointCenter: bigint[] = keyGen.pubKeyCompSECRev(pubKeyCenter);

    let pointToSearch: bigint[];

    //let step = 1024n * 1024n * 1024n;
    //let step = 1024n * 16n//1024n

    let step = 1024n * 1024n;

    //let step = 1024n

    
    let flag = false;
    let grate = 0; 
    let nonce = 0; 
    let cycle = 0; 

    for(let k = 0; k < rangeCycles && !flag; k++ ){

        cycle ++;


        if(rangeAmount > 0)
        {
            //Determina uma chave publica do tamanho (rangeAmount * 2 * step)
            pointToSearch = keyGen.keys.eccnP(BigInt(rangeAmount + k) * (2n * step), keyGen.keys.Gx, keyGen.keys.Gy);
            //Soma a chave de referencia a chave publica (rangeAmount * 2 * step) * G
            pointToSearch = keyGen.keys.addp(pointCenter[0], pointCenter[1], pointToSearch[0], pointToSearch[1]);
        }

        else if (rangeAmount < 0)
        {
            //Determina uma chave publica do tamanho (-1)*(rangeAmount * 2 * step)
            pointToSearch = keyGen.keys.eccnP(-1n * BigInt(rangeAmount - k) * (2n * step), keyGen.keys.Gx, keyGen.keys.Gy);
            //Substrai a chave de referencia a chave publica (rangeAmount * 2 * step) * G  
            pointToSearch = keyGen.keys.addp(pointCenter[0], pointCenter[1], pointToSearch[0], (keyGen.keys.p - pointToSearch[1]));
        }
        else
        {
            pointToSearch = pointCenter;
            //tem que sair não imoporta do tamanho do cycle
            k = rangeCycles;
        }
            
        console.log("pointCenter: ", pointToSearch[0].toString(16));

        let pubKeyAdd: bigint[] = pointToSearch;
        let pubKeySub = pubKeyAdd;

        //Testando a soma/subtração de um unico ponto

        grate = 0; 
        nonce = 0; 

        console.log("point ADD 0: ", pubKeyAdd[0].toString(16));
        console.log("point SUB 0: ", pubKeySub[0].toString(16));
        //for(let i = 0; i < step / (1024n); i ++){
        //////////////////////////////////////////////////////////////
        //Partindo de 0 checa 2^20 para frente e 2^20 para trás
        //  a some do step deve ser 2x
        //Partindo de 1 checa 2^20 para frente e 2^20 para trás
        //////////////////////////////////////////////////////////////

        //count = 0;

        //Verifica o ponto central contra o grade de (4096 * 64) = 262144 elementos se houve colisão;
        for(let j = 0; (j < grateNumber + 2) && !flag; j++){

            if(pointToSearch[0] === pbkSet[j]){
                flag = true
                grate = j;
                nonce = 0;
            }
        }

        //Analisa (2 * step) pontos contra toda a grade
        for(let i = 0; i < step && !flag; i ++){

            //Soma:
            pubKeyAdd = keyGen.keys.addp(pubKeyAdd[0], pubKeyAdd[1], keyGen.keys.Gx, keyGen.keys.Gy);
            //Subtração:
            pubKeySub = keyGen.keys.addp(pubKeySub[0], pubKeySub[1], keyGen.keys.Gx, (keyGen.keys.p - keyGen.keys.Gy));

            //Verifica na grade de (4096 * 64) = 262144 elementos se houve colisão;
            for(let j = 0; (j < grateNumber + 2) && !flag; j++){

                if(pubKeyAdd[0] === pbkSet[j]){
                    flag = true
                    grate = j;
                    nonce = i;
                }
                if(pubKeySub[0] === pbkSet[j]){
                    flag = true
                    grate = -j;
                    nonce = i;
                }
            }

            //console.log("pbkSet: ", pbkSet[1]);

            //console.log("point ADD: ", pubKeyAdd[0].toString(16));
            //console.log("point SUB: ", pubKeySub[0].toString(16));
            //console.log("Flag: ", flag);

            if(i % 10000 === 1)
            {
                console.log("pbkSet: ", pbkSet[i]);
                console.log("Searching: ", i)
                console.log("pointCenterAdd: ", pubKeyAdd);
                console.log("pointCenterSub: ", pubKeySub);
                console.log("Cycle: ", cycle)
            }

            //if(flag === true)
            //  break;

        }

    }

    console.log ("Flag: ", flag);
    console.log("Collision @: ", grate);
    console.log("Nonce: ", nonce);
    console.log("Range Cycles: ", rangeCycles);
    
    //setsendButton(true)
    return("Cycle: " + cycle + " Range: " + rangeAmount + " Flag: " + flag + " Collision @: " + grate + " Nonce: " + nonce);
  };
